create or replace function public.fleet_create_maintenance(p_business_id uuid,p_vehicle_id uuid,p_maintenance_type text,p_status text default 'scheduled',p_scheduled_at timestamptz default null,p_odometer_miles numeric default null,p_cost numeric default null,p_vendor text default null,p_notes text default null,p_metadata jsonb default '{}'::jsonb) returns public.fleet_maintenance_records language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $$ declare m public.fleet_maintenance_records; begin if not public.fleet_actor_is_manager(p_business_id) then raise exception 'Fleet manager access required'; end if; if p_vehicle_id is null or not exists(select 1 from public.fleet_vehicles where id=p_vehicle_id and business_id=p_business_id) then raise exception 'Vehicle not found'; end if; insert into public.fleet_maintenance_records(business_id,vehicle_id,maintenance_type,status,scheduled_at,odometer_miles,cost,vendor,notes,metadata) values(p_business_id,p_vehicle_id,nullif(trim(p_maintenance_type),''),coalesce(nullif(trim(p_status),''),'scheduled'),p_scheduled_at,p_odometer_miles,p_cost,nullif(trim(p_vendor),''),p_notes,coalesce(p_metadata,'{}'::jsonb)) returning * into m; return m; end $$;
create or replace function public.fleet_create_route(p_business_id uuid,p_name text,p_status text default 'planned',p_vehicle_id uuid default null,p_driver_id uuid default null,p_scheduled_for timestamptz default null,p_distance_miles numeric default null,p_estimated_minutes integer default null,p_stops_count integer default 0,p_metadata jsonb default '{}'::jsonb) returns public.fleet_routes language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $$ declare r public.fleet_routes; begin if not public.fleet_actor_is_manager(p_business_id) then raise exception 'Fleet manager access required'; end if; if nullif(trim(p_name),'') is null then raise exception 'Route name required'; end if; if p_vehicle_id is not null and not exists(select 1 from public.fleet_vehicles where id=p_vehicle_id and business_id=p_business_id) then raise exception 'Vehicle not found'; end if; if p_driver_id is not null and not exists(select 1 from public.fleet_drivers where id=p_driver_id and business_id=p_business_id) then raise exception 'Driver not found'; end if; insert into public.fleet_routes(business_id,name,status,vehicle_id,driver_id,scheduled_for,distance_miles,estimated_minutes,stops_count,metadata) values(p_business_id,trim(p_name),coalesce(nullif(trim(p_status),''),'planned'),p_vehicle_id,p_driver_id,p_scheduled_for,p_distance_miles,p_estimated_minutes,coalesce(p_stops_count,0),coalesce(p_metadata,'{}'::jsonb)) returning * into r; return r; end $$;
create or replace function public.fleet_delete_maintenance(p_business_id uuid,p_maintenance_id uuid) returns boolean language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $$ begin if not public.fleet_actor_is_manager(p_business_id) then raise exception 'Fleet manager access required'; end if; delete from public.fleet_maintenance_records where id=p_maintenance_id and business_id=p_business_id; return found; end $$;
create or replace function public.fleet_delete_route(p_business_id uuid,p_route_id uuid) returns boolean language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $$ begin if not public.fleet_actor_is_manager(p_business_id) then raise exception 'Fleet manager access required'; end if; delete from public.fleet_routes where id=p_route_id and business_id=p_business_id; return found; end $$;
create or replace function public.fleet_update_driver(p_business_id uuid,p_driver_id uuid,p_name text,p_email text,p_phone text,p_status text,p_vehicle_id uuid,p_metadata jsonb default '{}'::jsonb) returns public.fleet_drivers language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $$ declare d public.fleet_drivers; begin if not public.fleet_actor_is_manager(p_business_id) then raise exception 'Fleet manager access required'; end if; if p_vehicle_id is not null and not exists(select 1 from public.fleet_vehicles where id=p_vehicle_id and business_id=p_business_id) then raise exception 'Vehicle not found'; end if; update public.fleet_drivers set name=trim(p_name),email=nullif(trim(p_email),''),phone=nullif(trim(p_phone),''),status=nullif(trim(p_status),''),vehicle_id=p_vehicle_id,metadata=coalesce(p_metadata,metadata),updated_at=now() where id=p_driver_id and business_id=p_business_id returning * into d; if d.id is null then raise exception 'Driver not found'; end if; return d; end $$;
create or replace function public.fleet_update_maintenance(p_business_id uuid,p_maintenance_id uuid,p_vehicle_id uuid,p_maintenance_type text,p_status text,p_scheduled_at timestamptz,p_completed_at timestamptz,p_odometer_miles numeric,p_cost numeric,p_vendor text,p_notes text,p_metadata jsonb default '{}'::jsonb) returns public.fleet_maintenance_records language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $$ declare m public.fleet_maintenance_records; begin if not public.fleet_actor_is_manager(p_business_id) then raise exception 'Fleet manager access required'; end if; if p_vehicle_id is null or not exists(select 1 from public.fleet_vehicles where id=p_vehicle_id and business_id=p_business_id) then raise exception 'Vehicle not found'; end if; update public.fleet_maintenance_records set vehicle_id=p_vehicle_id,maintenance_type=nullif(trim(p_maintenance_type),''),status=nullif(trim(p_status),''),scheduled_at=p_scheduled_at,completed_at=p_completed_at,odometer_miles=p_odometer_miles,cost=p_cost,vendor=nullif(trim(p_vendor),''),notes=p_notes,metadata=coalesce(p_metadata,metadata),updated_at=now() where id=p_maintenance_id and business_id=p_business_id returning * into m; if m.id is null then raise exception 'Maintenance record not found'; end if; return m; end $$;
create or replace function public.fleet_update_route(p_business_id uuid,p_route_id uuid,p_name text,p_status text,p_vehicle_id uuid,p_driver_id uuid,p_scheduled_for timestamptz,p_distance_miles numeric,p_estimated_minutes integer,p_stops_count integer,p_metadata jsonb default '{}'::jsonb) returns public.fleet_routes language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $$ declare r public.fleet_routes; begin if not public.fleet_actor_is_manager(p_business_id) then raise exception 'Fleet manager access required'; end if; if p_vehicle_id is not null and not exists(select 1 from public.fleet_vehicles where id=p_vehicle_id and business_id=p_business_id) then raise exception 'Vehicle not found'; end if; if p_driver_id is not null and not exists(select 1 from public.fleet_drivers where id=p_driver_id and business_id=p_business_id) then raise exception 'Driver not found'; end if; update public.fleet_routes set name=trim(p_name),status=nullif(trim(p_status),''),vehicle_id=p_vehicle_id,driver_id=p_driver_id,scheduled_for=p_scheduled_for,distance_miles=p_distance_miles,estimated_minutes=p_estimated_minutes,stops_count=coalesce(p_stops_count,0),metadata=coalesce(p_metadata,metadata),updated_at=now() where id=p_route_id and business_id=p_business_id returning * into r; if r.id is null then raise exception 'Route not found'; end if; return r; end $$;
create or replace function public.fleet_update_vehicle(p_business_id uuid,p_vehicle_id uuid,p_name text,p_unit_code text,p_vehicle_type text,p_status text,p_driver_name text,p_current_lat double precision,p_current_lng double precision,p_odometer_miles numeric,p_metadata jsonb default '{}'::jsonb) returns public.fleet_vehicles language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $$ declare v public.fleet_vehicles; begin if not public.fleet_actor_is_manager(p_business_id) then raise exception 'Fleet manager access required'; end if; update public.fleet_vehicles set name=trim(p_name),unit_code=nullif(trim(p_unit_code),''),vehicle_type=nullif(trim(p_vehicle_type),''),status=nullif(trim(p_status),''),driver_name=nullif(trim(p_driver_name),''),current_lat=p_current_lat,current_lng=p_current_lng,odometer_miles=p_odometer_miles,metadata=coalesce(p_metadata,metadata),updated_at=now() where id=p_vehicle_id and business_id=p_business_id returning * into v; if v.id is null then raise exception 'Vehicle not found'; end if; return v; end $$;
